void riscplay_audio_set_adsr(uint8_t ch,uint8_t a,uint8_t d,uint8_t s,uint8_t r) {
    uint32_t v=(a&15u)|((uint32_t)(d&15u)<<4)|((uint32_t)(s&15u)<<8)|((uint32_t)(r&15u)<<12);
