}
uint8_t riscplay_audio_sfx_active(void) { return sfx_channel!=255u; }
void riscplay_audio_update_ms(uint32_t elapsed_ms) {
    /* Avoid integer overflow and process elapsed time in bounded chunks. */
    while(elapsed_ms) {
