    /* Scale the measured MMIO clock while preserving fractional ticks.
       Clamp AFTER conversion to avoid skipping musical time on long frames. */
    uint32_t scaled = elapsed / RP_AUDIO_TIMER_DIVISOR;
    uint32_t fraction = elapsed % RP_AUDIO_TIMER_DIVISOR;
    timer_fraction += fraction;
    if (timer_fraction >= RP_AUDIO_TIMER_DIVISOR) {
        timer_fraction -= RP_AUDIO_TIMER_DIVISOR;
        scaled++;
    }
    if (scaled > 100u) scaled = 100u;
    riscplay_audio_update_ms(scaled);
}

